def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = adj[i]
            nbrs = [j for j in range(n) if row[j] == 1 and j != i]
            neighbors.append(nbrs)
    else:
        neighbors = [list(lst) for lst in adj]
    # Ensure symmetry and remove duplicates
    for i in range(n):
        neighbors[i] = list(set(neighbors[i]))
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].append(i)
    # Remove self-loops if any
    for i in range(n):
        if i in neighbors[i]:
            neighbors[i].remove(i)
    # Edge case: no edges
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n
    # DSATUR heuristic
    color = [-1] * n
    sat = [0] * n
    # Order by degree descending for initial tie-breaking
    order = list(range(n))
    order.sort(key=lambda x: len(neighbors[x]), reverse=True)
    for _ in range(n):
        # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph, then order
        v = -1
        max_sat = -1
        max_deg = -1
        for u in order:
            if color[u] == -1:
                if sat[u] > max_sat:
                    max_sat = sat[u]
                    max_deg = len([w for w in neighbors[u] if color[w] == -1])
                    v = u
                elif sat[u] == max_sat:
                    deg_u = len([w for w in neighbors[u] if color[w] == -1])
                    if deg_u > max_deg:
                        max_deg = deg_u
                        v = u
                    elif deg_u == max_deg:
                        # Tie-break by original order index
                        if order.index(u) < order.index(v):
                            v = u
        # Assign smallest available color
        used = [False] * (n + 1)
        for w in neighbors[v]:
            cw = color[w]
            if cw != -1:
                used[cw] = True
        c = 0
        while c <= n and used[c]:
            c += 1
        color[v] = c
        # Update saturation of neighbors
        for w in neighbors[v]:
            if color[w] == -1:
                # Count distinct colors in neighborhood of w
                seen = set()
                for nb in neighbors[w]:
                    cn = color[nb]
                    if cn != -1:
                        seen.add(cn)
                sat[w] = len(seen)
    # Try to reduce number of colors using Kempe chain swaps
    max_color = max(color) if n > 0 else 0
    improved = True
    while improved and max_color > 0:
        improved = False
        # Try to eliminate color classes from highest to lowest
        for target_color in range(max_color, 0, -1):
            # Collect vertices with target_color
            vc = [i for i in range(n) if color[i] == target_color]
            if not vc:
                continue
            # Try to recolor each vertex in vc to a lower color
            for v in vc:
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    conflict = False
                    for w in neighbors[v]:
                        if color[w] == c:
                            conflict = True
                            break
                    if not conflict:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swap
                for c in range(target_color):
                    # Find the Kempe chain component of v for colors (target_color, c)
                    # BFS/DFS to get component
                    stack = [v]
                    visited = [False] * n
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for w in neighbors[node]:
                            if not visited[w] and (color[w] == target_color or color[w] == c):
                                visited[w] = True
                                stack.append(w)
                    # Check if any neighbor of v has color c (outside component)
                    has_c_neighbor = False
                    for w in neighbors[v]:
                        if color[w] == c and not visited[w]:
                            has_c_neighbor = True
                            break
                    if not has_c_neighbor:
                        # Swap colors in component
                        for node in component:
                            if color[node] == target_color:
                                color[node] = c
                            elif color[node] == c:
                                color[node] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # Recompute max_color
                max_color = max(color)
                break
        if not improved:
            break
    return color

