        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list from input
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        # Already adjacency list, but ensure it's a list of lists
        adj_list = [list(neighbors) for neighbors in adj]

    # Precompute degrees for tie-breaking
    degree = [len(adj_list[i]) for i in range(n)]

    # DSATUR algorithm
    colors = [-1] * n  # -1 indicates uncolored
    # saturation[v] = set of colors used by colored neighbors
    saturation = [set() for _ in range(n)]
    # Track uncolored vertices
    uncolored = set(range(n))

    # Helper to get degree in uncolored subgraph
    def degree_in_uncolored(v):
        count = 0
        for u in adj_list[v]:
            if u in uncolored:
                count += 1
        return count

    # Main loop: color vertices one by one
    while uncolored:
        # Select vertex with maximum saturation degree
        max_sat = -1
        candidates = []
        for v in uncolored:
            sat = len(saturation[v])
            if sat > max_sat:
                max_sat = sat
                candidates = [v]
            elif sat == max_sat:
                candidates.append(v)

        # Tie-break: maximum degree in uncolored subgraph
        if len(candidates) > 1:
            max_deg = -1
            new_candidates = []
            for v in candidates:
                deg = degree_in_uncolored(v)
                if deg > max_deg:
                    max_deg = deg
                    new_candidates = [v]
                elif deg == max_deg:
                    new_candidates.append(v)
            candidates = new_candidates

        # Final tie-break: random choice (or min index for determinism, but random helps escape local optima)
        v = random.choice(candidates)

        # Find smallest available color (mex)
        used = saturation[v]
        c = 0
        while c in used:
            c += 1
        colors[v] = c
        uncolored.remove(v)

        # Update saturation of uncolored neighbors
        for u in adj_list[v]:
            if u in uncolored:
                saturation[u].add(c)

    return colors

