import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Convert matrix to adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        # Treat as adjacency list
        graph = [list(neighbors) for neighbors in adj]

    # Ensure symmetry and no self-loops
    for i in range(n):
        if i in graph[i]:
            graph[i].remove(i)
        for j in graph[i]:
            if i not in graph[j]:
                graph[j].append(i)

    # Helper: DSATUR-based coloring
    def dsatur_coloring():
        color = [-1] * n
        saturation = [set() for _ in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = max(uncolored, key=lambda x: (len(saturation[x]), len([nbr for nbr in graph[x] if nbr in uncolored]), random.random()))
            # Find smallest available color
            used = {color[nbr] for nbr in graph[v] if color[nbr] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for nbr in graph[v]:
                if nbr in uncolored:
                    saturation[nbr].add(c)
        return color

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf_coloring():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (len([nbr for nbr in graph[x] if nbr in uncolored]), random.random()))
            S.add(v)
            uncolored.remove(v)
            # U: vertices not adjacent to S (eligible), W: vertices adjacent to S (ineligible)
            U = {u for u in uncolored if all(u not in graph[w] for w in S)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([nbr for nbr in graph[x] if nbr in W]), -len([nbr for nbr in graph[x] if nbr in U]), random.random()))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nbr in graph[u]:
                    if nbr in U:
                        U.remove(nbr)
                        W.add(nbr)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
            uncolored = W  # Next iteration colors the ineligible vertices
        return color

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last_coloring():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len([nbr for nbr in graph[v] if nbr in remaining]) for v in range(n)]
        # Use bucket sort for efficiency
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if deg[v] < len(buckets):
                buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr < len(buckets) and not buckets[ptr]:
                ptr += 1
            if ptr >= len(buckets):
                break  # Should not happen
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for nbr in graph[v]:
                if nbr in remaining:
                    old_deg = deg[nbr]
                    deg[nbr] -= 1
                    if old_deg < len(buckets):
                        buckets[old_deg].remove(nbr)
                    if deg[nbr] < len(buckets):
                        buckets[deg[nbr]].append(nbr)
                    if deg[nbr] < ptr:
                        ptr = deg[nbr]
        # Color in reverse order using First-Fit
        color = [-1] * n
        for v in reversed(order):
            used = {color[nbr] for nbr in graph[v] if color[nbr] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Helper: Kempe chain local search for color reduction
    def kempe_reduce(color):
        # Helper to get color classes
        def get_color_classes():
            classes = {}
            for v in range(n):
                c = color[v]
                if c not in classes:
                    classes[c] = set()
                classes[c].add(v)
            return classes

        classes = get_color_classes()
        if not classes:
            return color
        max_color = max(classes.keys())
        # Try to eliminate color classes from highest down
        for target_color in range(max_color, 0, -1):
            if target_color not in classes or not classes[target_color]:
                continue
            # Try to recolor each vertex in target_color
            changed = True
            while changed and target_color in classes and classes[target_color]:
                changed = False
                v = next(iter(classes[target_color]))
                # Try direct move to lower color
                for c in range(target_color):
                    if all(color[nbr] != c for nbr in graph[v]):
                        # Move v to color c
                        classes[target_color].remove(v)
                        if not classes[target_color]:
                            del classes[target_color]
                        color[v] = c
                        if c not in classes:
                            classes[c] = set()
                        classes[c].add(v)
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chain swap
                for c in range(target_color):
                    # Skip if v already has color c (shouldn't happen)
                    if color[v] == c:
                        continue
                    # Find the Kempe chain component of v in colors {target_color, c}
                    visited = set()
                    stack = [v]
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if color[node] == target_color or color[node] == c:
                            component.add(node)
                            for nbr in graph[node]:
                                if nbr not in visited and (color[nbr] == target_color or color[nbr] == c):
                                    stack.append(nbr)
                    # Check if swapping this component is safe: no neighbor outside component has color c
                    safe = True
                    for node in component:
                        for nbr in graph[node]:
                            if nbr not in component and color[nbr] == c:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # Perform swap: target_color <-> c in component
                        for node in component:
                            old_color = color[node]
                            new_color = c if old_color == target_color else target_color
                            color[node] = new_color
                            # Update classes
                            classes[old_color].remove(node)
                            if not classes[old_color]:
                                del classes[old_color]
                            if new_color not in classes:
                                classes[new_color] = set()
                            classes[new_color].add(node)
                        changed = True
                        break
                # If no change, break inner while
            # If target_color class is empty, we reduced the number of colors
            if target_color not in classes or not classes[target_color]:
                # Reindex colors to be contiguous? Not necessary for correctness, but we can leave gaps.
                # However, we want to minimize the number, so we continue to try lower targets.
                pass
        return color

    # Run multiple algorithms and pick the best (smallest number of colors)
    best_coloring = None
    best_num_colors = float('inf')

    # List of coloring functions to try
    colorings = [
        ("DSATUR", dsatur_coloring),
        ("RLF", rlf_coloring),
        ("Smallest-Last", smallest_last_coloring),
    ]

    for name, func in colorings:
        try:
            col = func()
            # Validate coloring
            valid = True
            for u in range(n):
                for v in graph[u]:
                    if u < v and col[u] == col[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                num_colors = len(set(col))
                if num_colors < best_num_colors or (num_colors == best_num_colors and best_coloring is None):
                    best_num_colors = num_colors
                    best_coloring = col[:]
        except Exception:
            continue

    # Apply Kempe reduction to improve the best found
    if best_coloring is not None:
        try:
            improved = kempe_reduce(best_coloring[:])
            # Validate
            valid = True
            for u in range(n):
                for v in graph[u]:
                    if u < v and improved[u] == improved[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                num_colors = len(set(improved))
                if num_colors < best_num_colors:
                    best_num_colors = num_colors
                    best_coloring = improved
        except Exception:
            pass

    # Fallback: greedy by degree if nothing worked
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: (-len(graph[x]), random.random()))
        color = [-1] * n
        for v in order:
            used = {color[nbr] for nbr in graph[v] if color[nbr] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        best_coloring = color

    return best_coloring

