def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix: square and entries are 0 or 1
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val != 0 and val != 1:
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build neighbor list
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = adj[i]
            nbrs = [j for j in range(n) if row[j] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = adj  # assume adjacency list
    # Trivial cases
    if n == 1:
        return [0]
    # Check if edgeless
    edgeless = True
    for nbrs in neighbors:
        if nbrs:
            edgeless = False
            break
    if edgeless:
        return [0] * n
    # Check if complete graph
    complete = True
    for i in range(n):
        if len(neighbors[i]) != n - 1:
            complete = False
            break
    if complete:
        return list(range(n))
    # DSATUR with tie-breaking by degree in uncolored subgraph
    color = [-1] * n
    saturated = [set() for _ in range(n)]
    uncolored = set(range(n))
    # Precompute degrees
    degrees = [len(neighbors[i]) for i in range(n)]
    while uncolored:
        # Select vertex with max saturation degree, tie-break by degree in uncolored subgraph, then random
        v = max(uncolored, key=lambda x: (len(saturated[x]), degrees[x], random.random()))
        # Find smallest available color
        used = saturated[v]
        c = 0
        while c in used:
            c += 1
        color[v] = c
        uncolored.remove(v)
        # Update saturation sets of uncolored neighbors
        for u in neighbors[v]:
            if u in uncolored:
                saturated[u].add(c)
    # Try to reduce number of colors using Kempe chain swaps
    max_color = max(color) if n > 0 else -1
    for k in range(max_color, 0, -1):
        # Vertices with color k
        verts_k = [i for i in range(n) if color[i] == k]
        if not verts_k:
            continue
        moved = True
        while moved and verts_k:
            moved = False
            # Try to recolor each vertex in color k
            for v in verts_k[:]:  # iterate over a copy
                # Try direct move to a lower color
                for c in range(k):
                    conflict = False
                    for u in neighbors[v]:
                        if color[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Move v to color c
                        color[v] = c
                        verts_k.remove(v)
                        moved = True
                        break
                if moved:
                    continue
                # Try Kempe chain swap for each lower color
                for c in range(k):
                    # BFS to get the (k,c)-Kempe chain component containing v
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    while stack:
                        node = stack.pop()
                        for u in neighbors[node]:
                            if u not in visited and (color[u] == k or color[u] == c):
                                visited.add(u)
                                stack.append(u)
                    # Check if any neighbor of v has color c (which would cause conflict after swap)
                    has_c_neighbor = False
                    for u in neighbors[v]:
                        if color[u] == c:
                            has_c_neighbor = True
                            break
                    if not has_c_neighbor:
                        # Swap colors k and c in the component
                        for node in visited:
                            if color[node] == k:
                                color[node] = c
                            elif color[node] == c:
                                color[node] = k
                        # After swap, v now has color c
                        verts_k.remove(v)
                        moved = True
                        break
                if moved:
                    break
        if not verts_k:
            # Successfully eliminated color k
            # Remap colors > k down by 1
            for i in range(n):
                if color[i] > k:
                    color[i] -= 1
        else:
            # Could not eliminate color k, break
            break
    return color

