def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix: square and binary entries
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets for O(1) adjacency checks
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n and i != j:
                    neighbors[i].add(j)

    # Trivial cases
    if n == 1:
        return [0]
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n
    if all(len(neighbors[i]) == n - 1 for i in range(n)):
        return list(range(n))

    # Precompute degrees
    degree = [len(neighbors[i]) for i in range(n)]

    # Helper: mex (minimum excluded value)
    def mex(s):
        c = 0
        while c in s:
            c += 1
        return c

    # DSATUR core: returns coloring and number of colors used
    def dsatur():
        color = [-1] * n
        saturation = [0] * n  # number of distinct colors in neighborhood

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if color[i] == -1:
                    sat_i = saturation[i]
                    deg_i = sum(1 for nb in neighbors[i] if color[nb] == -1)
                    if sat_i > max_sat or (sat_i == max_sat and deg_i > max_deg) or \
                       (sat_i == max_sat and deg_i == max_deg and (v == -1 or random.random() < 0.5)):
                        max_sat = sat_i
                        max_deg = deg_i
                        v = i
            # Assign smallest available color
            forbidden = set()
            for nb in neighbors[v]:
                if color[nb] != -1:
                    forbidden.add(color[nb])
            c = mex(forbidden)
            color[v] = c
            # Update saturation of uncolored neighbors
            for nb in neighbors[v]:
                if color[nb] == -1:
                    saturation[nb] += 1
        return color

    # RLF core: independent set extraction
    def rlf():
        color = [-1] * n
        colored = [False] * n
        c = 0

        while not all(colored):
            # Uncolored vertices
            R = [i for i in range(n) if not colored[i]]
            if not R:
                break
            # Start with max degree vertex in R
            v = max(R, key=lambda x: sum(1 for nb in neighbors[x] if not colored[nb]))
            S = [v]
            colored[v] = True
            # W: neighbors of S (ineligible)
            W = set()
            for nb in neighbors[v]:
                if not colored[nb]:
                    W.add(nb)
            # U: uncolored and not adjacent to S (eligible)
            U = set(R) - {v} - W

            # Grow independent set S
            while U:
                # Select u in U maximizing |N(u) ∩ W|, tie-break by min degree in U
                best_u = None
                max_w = -1
                min_deg_u = math.inf
                for u in U:
