    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n and i != j:
                    neighbors[i].add(j)
    # Ensure symmetry (undirected graph)
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)

