    degree = [len(neighbors[i]) for i in range(n)]

    # Helper: mex of a set of colors
    def mex(s):
        c = 0
        while c in s:
            c += 1
        return c

    # DSATUR core: returns (coloring, num_colors)
    def dsatur():
        color = [-1] * n
        saturation = [0] * n  # number of distinct colors in neighborhood
        # Start with highest degree vertex
        v = max(range(n), key=lambda x: degree[x])
        color[v] = 0
        for u in neighbors[v]:
            if color[u] == -1:
                saturation[u] = 1  # neighbor now sees color 0
        # Color remaining vertices
        for _ in range(n - 1):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if color[i] == -1:
                    sat_i = saturation[i]
                    deg_i = degree[i]
                    if sat_i > max_sat or (sat_i == max_sat and deg_i > max_deg) or \
                       (sat_i == max_sat and deg_i == max_deg and random.random() < 0.5):
                        max_sat = sat_i
                        max_deg = deg_i
                        v = i
            # Assign smallest available color
            forbidden = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    forbidden.add(color[u])
            c = mex(forbidden)
            color[v] = c
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if color[u] == -1:
                    # Recompute saturation: count distinct colors in neighborhood
                    seen = set()
                    for w in neighbors[u]:
                        if color[w] != -1:
                            seen.add(color[w])
                    saturation[u] = len(seen)
