    def rlf():
        color = [-1] * n
        colored = [False] * n
        current_color = 0
        # Helper: degree in uncolored subgraph
        def uncolored_degree(v):
            return sum(1 for u in neighbors[v] if not colored[u])

        while not all(colored):
            # Pick uncolored vertex with max degree in uncolored subgraph
            uncolored = [i for i in range(n) if not colored[i]]
            v = max(uncolored, key=uncolored_degree)

            # Build independent set S for color current_color
            S = [v]
            colored[v] = True
