            for node in S:
                color[node] = current_color
            current_color += 1

        return color, max(color) + 1 if n > 0 else 0

    # Get initial colorings from DSATUR and RLF
    col1, k1 = dsatur()
    col2, k2 = rlf()

    # Choose the better initial coloring
    if k1 <= k2:
        best_color, best_k = col1, k1
    else:
        best_color, best_k = col2, k2

    # Kempe chain refinement to reduce color count
    def kempe_refine(coloring, k):
        if k <= 1:
            return coloring, k
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, 0, -1):
            # Vertices with target_color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                continue  # already eliminated

            # Try to recolor each vertex in this class
            eliminated = True
            new_coloring = coloring[:]  # work on a copy

            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = {new_coloring[u] for u in neighbors[v]}
                moved = False
                for c in range(target_color):
                    if c not in neighbor_colors:
                        new_coloring[v] = c
                        moved = True
                        break
                if moved:
                    continue

                # Try Kempe chain swap for each lower color c
                kempe_success = False
                for c in range(target_color):
                    # Find the (c, target_color)-Kempe chain component containing v
                    stack = [v]
                    visited = [False] * n
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in neighbors[node]:
                            if not visited[nb] and (new_coloring[nb] == c or new_coloring[nb] == target_color):
                                visited[nb] = True
                                stack.append(nb)
                    # Check if swapping is safe: no neighbor outside component has color c
                    # (to avoid pulling vertices into target_color class)
                    conflict = False
                    for node in component:
                        for nb in neighbors[node]:
                            if not visited[nb] and new_coloring[nb] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Perform swap: c <-> target_color in component
                        for node in component:
                            if new_coloring[node] == c:
                                new_coloring[node] = target_color
                            else:  # must be target_color
                                new_coloring[node] = c
                        kempe_success = True
                        break  # break c-loop, move to next v
                if not kempe_success:
                    eliminated = False
                    break  # cannot eliminate this color class

            if eliminated:
                # Successfully eliminated target_color, recurse
                return kempe_refine(new_coloring, k - 1)

        return coloring, k

    # Apply Kempe refinement
    best_color, best_k = kempe_refine(best_color, best_k)

    # Remap colors to be contiguous starting from 0 (in case of gaps)
    used_colors = set(best_color)
    if not used_colors:
        return [0] * n
    mapping = {old: new for new, old in enumerate(sorted(used_colors))]
    return [mapping[c] for c in best_color]

