    # Kempe chain refinement: try to eliminate color classes from highest down
    def kempe_refine(coloring):
        k = max(coloring) + 1 if n > 0 else 0
        if k <= 1:
            return coloring

        # Try to eliminate each color class from k-1 down to 1
        for target in range(k - 1, 0, -1):
            verts = [v for v in range(n) if coloring[v] == target]
            if not verts:
                continue  # already eliminated

            new_coloring = coloring[:]  # work on a copy
            success = True
            for v in verts:
                # Try direct reassignment to a lower color
                moved = False
                for c in range(target):
                    if all(new_coloring[u] != c for u in neighbors[v]):
                        new_coloring[v] = c
                        moved = True
                        break
                if moved:
                    continue

                # Try Kempe chain swap for each lower color c
                for c in range(target):
                    # Build (target, c)-Kempe component containing v via BFS
                    stack = [v]
                    visited = [False] * n
                    visited[v] = True
                    comp_target = []
                    comp_c = []
                    while stack:
                        node = stack.pop()
                        if coloring[node] == target:
                            comp_target.append(node)
                        elif coloring[node] == c:
                            comp_c.append(node)
                        else:
                            continue  # should not happen in Kempe chain
                        for nb in neighbors[node]:
                            if not visited[nb] and coloring[nb] in (target, c):
                                visited[nb] = True
                                stack.append(nb)
                    # Swap colors in component: target <-> c
                    for node in comp_target:
                        new_coloring[node] = c
                    for node in comp_c:
                        new_coloring[node] = target
                    # After swap, v has color c (was in comp_target)
                    # Check if v has any neighbor with color target in original coloring
                    # (because after swap, such neighbor becomes c and conflicts with v's new color c)
                    has_target_neighbor = any(coloring[u] == target for u in neighbors[v])
                    if not has_target_neighbor:
                        moved = True
                        break
                if moved:
                    # Successfully recolored v to a lower color
                    continue
                else:
                    # Could not recolor v
                    success = False
                    break
            if success:
                # Successfully eliminated color class 'target', recurse
                return kempe_refine(new_coloring)
        return coloring

    # Get initial coloring from DSATUR
    best_col = dsatur()
    best_k = max(best_col) + 1 if n > 0 else 0

    # Apply Kempe refinement with multiple random restarts to improve solution
    # Time-bound: for N<=100, a few iterations are safe within 50ms
    for _ in range(3):  # Limited restarts for speed
        # Apply Kempe refinement
        refined = kempe_refine(best_col)
        refined_k = max(refined) + 1 if n > 0 else 0
        if refined_k < best_k:
            best_col = refined
            best_k = refined_k
        # Apply a small random perturbation to escape local optima
        # Only if we haven't reached the theoretical lower bound (clique size)
        if best_k > max(deg) + 1:  # Only perturb if not already optimal
            # Create a copy and randomly swap colors of two non-adjacent vertices
            perturbed = best_col[:]
            attempts = 0
            while attempts < 10:  # Try to find a valid swap
                i, j = random.sample(range(n), 2)
                if j not in neighbors[i]:  # Non-adjacent
                    perturbed[i], perturbed[j] = perturbed[j], perturbed[i]
                    # Check if still valid
                    valid = True
                    for u in range(n):
                        for v in neighbors[u]:
                            if u < v and perturbed[u] == perturbed[v]:
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        best_col = perturbed
                        break
                attempts += 1

    # Finalize: ensure colors are contiguous (0..k-1)
    used = set(best_col)
    if not used:
        return [0] * n
    mapping = {old: new for new, old in enumerate(sorted(used))}
    return [mapping[c] for c in best_col]
